<section class="inner-hero compact"><div class="inner-hero-art managed-art" style="--page-image:url('<?=e(safe_image($page['image_path']??null,'images/demo/campaign-families.jpg'))?>')"></div><div class="inner-hero-shade"></div><div class="container inner-hero-content reveal"><span class="eyebrow"><?=e($page['eyebrow']??'FUNDRAISING')?></span><h1><?=e($page['hero_title']??'Campaigns')?></h1><p><?=e($page['hero_subtitle']??'Only administrator-approved donations are included in public raised totals.')?></p></div></section>
<section class="section campaign-listing"><div class="container"><div class="campaign-grid wide"><?php foreach($campaigns as $idx=>$c):$pct=$c['target_amount']>0?min(100,round($c['raised']/$c['target_amount']*100)):0;$fallback=['images/demo/campaign-families.jpg','images/demo/campaign-education.jpg','images/demo/campaign-health.jpg'][$idx%3];?><article class="campaign-card reveal"><a class="campaign-image tall" href="<?=url('campaigns/'.$c['slug'])?>" data-spa-link><img src="<?=e($c['cover_image']?public_upload($c['cover_image']):asset($fallback))?>" alt="<?=e($c['title'])?>"><span><?=e(ucfirst($c['status']))?></span></a><div class="campaign-body"><small class="campaign-category"><?=e($c['category']?:'Community Support')?></small><h3><?=e($c['title'])?></h3><p><?=e($c['short_description']??'')?></p><div class="amount-line"><span>Raised <b><?=money($c['raised'],$c['currency'])?></b></span><b><?=$pct?>%</b></div><div class="progress"><i style="width:<?=$pct?>%"></i></div><div class="goal">Goal <?=money($c['target_amount'],$c['currency'])?></div><div class="card-actions"><a class="btn btn-soft" href="<?=url('campaigns/'.$c['slug'])?>" data-spa-link>View Details</a><?php if($c['status']==='active'):?><a class="btn btn-primary" href="<?=url('donate?campaign='.$c['id'])?>">Donate Now</a><?php endif;?></div></div></article><?php endforeach;?><?php if(!$campaigns):?><div class="empty-state premium-empty">There are no public fundraising campaigns at the moment.</div><?php endif;?></div></div></section>

